import { useCallback, useEffect, useRef } from 'react';
import type { RefObject } from 'react';

interface ScrollPosition {
  readonly left: number;
  readonly top: number;
}

// Chromium centers a card that Tab or Shift+Tab focuses inside the board before focus handlers
// run. Scroll events arrive a frame later, so the last board position they reported still shows
// the view from before that scroll. Restoring it first lets the card scroll from where the player
// was looking, with nearest alignment in the board. The page scroll is left to the browser.
export function useNearestScroll(viewport: RefObject<HTMLElement | null>) {
  const board = useRef<ScrollPosition>({ left: 0, top: 0 });
  useEffect(() => {
    const element = viewport.current;
    function boardScrolled(): void {
      if (element) board.current = { left: element.scrollLeft, top: element.scrollTop };
    }
    boardScrolled();
    element?.addEventListener('scroll', boardScrolled, { passive: true });
    return () => element?.removeEventListener('scroll', boardScrolled);
  }, [viewport]);

  return useCallback(
    (card: HTMLElement): void => {
      viewport.current?.scrollTo(board.current.left, board.current.top);
      card.scrollIntoView({ block: 'nearest', inline: 'nearest' });
    },
    [viewport],
  );
}
import { expect, Scrollbars, test } from './browser-test.ts';
import { DealControl } from '../src/game/controls/control-labels.ts';
import { loadFixedBoard } from './game-fixture.ts';

const CARD_MIN_PX = 44;
// Each board scrolls the page, and the larger ones also scroll the board vertically.
const BOARDS = [
  { width: 1280, height: 800, size: 16 },
  { width: 900, height: 600, size: 10 },
  { width: 1000, height: 600, size: 12 },
  { width: 360, height: 640, size: 6 },
] as const;

for (const { width, height, size } of BOARDS) {
  test(
    `a ${size}x${size} board fits beside visible scrollbars at ${width}x${height}`,
    async ({ page }) => {
      await page.setViewportSize({ width, height });
      await loadFixedBoard(page);
      await page.getByLabel(DealControl.size, { exact: true }).selectOption(String(size));
      await expect(page.locator('.card')).toHaveCount(size ** 2);
      const layout = await page.locator('.board-viewport').evaluate((element) => ({
        pageScrollbar: innerWidth - document.documentElement.clientWidth,
        pageOverflow: document.documentElement.scrollWidth - document.documentElement.clientWidth,
        boardOverflow: element.scrollWidth - element.clientWidth,
        card: element.querySelector('.card')?.getBoundingClientRect().width ?? 0,
      }));
      expect(layout.pageScrollbar, 'visible scrollbars take layout space').toBeGreaterThan(0);
      expect(layout.pageOverflow, 'V02 page stays within the viewport').toBe(0);
      expect(layout.card, 'cards stay above their minimum').toBeGreaterThan(CARD_MIN_PX);
      expect(layout.boardOverflow, 'V04 board fits beside its scrollbars').toBe(0);
    },
    {},
    Scrollbars.visible,
  );
}
import { useEffect } from 'react';
import { writePreferences } from './storage.ts';
import type { Preferences, PreferenceStore } from './storage.ts';

// Reading localStorage can throw when the browser blocks storage, and play continues without it.
export function browserStore(): PreferenceStore | null {
  try {
    return window.localStorage;
  } catch {
    return null;
  }
}

// Saves this tab's size and bests after each change.
export function useSavedPreferences(store: PreferenceStore | null, preferences: Preferences) {
  useEffect(() => {
    writePreferences(store, preferences);
  }, [preferences, store]);
}

